import{_ as r,a0 as t,w as l,s as d,I as n,x as a,a1 as i,A as p,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 mergefs 增加虛擬存儲 | LCTT x X-CMD","titleTemplate":false,"description":"使用 mergefs 增加虛擬存儲 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 mergefs 增加虛擬存儲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 mergefs 增加虛擬存儲 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200501 Using mergerfs to increase your virtual storage","title":"使用 mergefs 增加虛擬存儲","tag":"202005","desc":""},"relativePath":"202005/20200501 Using mergerfs to increase your virtual storage.md","filePath":"[post].md"}'),g={name:"202005/20200501 Using mergerfs to increase your virtual storage.md"};function u(c,s,m,f,k,h){const e=t("Link");return l(),d("div",null,[s[22]||(s[22]=n("h1",{id:"使用-mergefs-增加虛擬存儲",tabindex:"-1"},[a("使用 mergefs 增加虛擬存儲 "),n("a",{class:"header-anchor",href:"#使用-mergefs-增加虛擬存儲","aria-label":"Permalink to “使用 mergefs 增加虛擬存儲”"},"​")],-1)),s[23]||(s[23]=n("p",null,[n("img",{src:"https://fedoramagazine.org/wp-content/uploads/2020/04/mergerfs-816x346.png",alt:""})],-1)),s[24]||(s[24]=n("p",null,"如果你想在一個媒體項目中用到了多個磁盤或分區，不想丟失任何現有數據，但又想將所有文件都存放在一個驅動器下，該怎麼辦？這時，mergefs 就能派上用場！",-1)),n("p",null,[i(e,{href:"https://github.com/trapexit/mergerfs"},{default:p(()=>[...s[0]||(s[0]=[a("mergerfs",-1)])]),_:1}),s[1]||(s[1]=a(" 是一個聯合文件系統，旨在簡化存儲和管理眾多商業存儲設備上的文件。",-1))]),n("p",null,[s[4]||(s[4]=a("你需要從他們的 ",-1)),i(e,{href:"https://github.com/trapexit/mergerfs/releases"},{default:p(()=>[...s[2]||(s[2]=[a("GitHub",-1)])]),_:1}),s[5]||(s[5]=a(" 頁面獲取最新的 RPM。Fedora 的版本名稱中帶有 “fc” 和版本號。例如，這是 Fedora 31 的版本： ",-1)),i(e,{href:"https://github.com/trapexit/mergerfs/releases/download/2.29.0/mergerfs-2.29.0-1.fc31.x86_64.rpm"},{default:p(()=>[...s[3]||(s[3]=[a("mergerfs-2.29.0-1.fc31.x86_64.rpm",-1)])]),_:1}),s[6]||(s[6]=a("。",-1))]),s[25]||(s[25]=o(`<h3 id="安裝和配置-mergefs" tabindex="-1">安裝和配置 mergefs <a class="header-anchor" href="#安裝和配置-mergefs" aria-label="Permalink to “安裝和配置 mergefs”">​</a></h3><p>使用 <code>sudo</code> 安裝已下載的 mergefs 軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install mergerfs-2.29.0-1.fc31.x86_64.rpm</span></span></code></pre></div><p>現在，你可以將多個磁盤掛載為一個驅動器。如果你有一台媒體服務器，並且希望所有媒體文件都顯示在一個地方，這將很方便。如果將新文件上傳到系統，那麼可以將它們複製到 mergefs 目錄，mergefs 會自動將它們複製具有足夠可用空間的磁盤上。</p><p>這是使你更容易理解的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -hT | grep disk</span></span>
<span class="line"><span>/dev/sdb1      ext4      23M  386K 21M 2% /disk1</span></span>
<span class="line"><span>/dev/sdc1      ext4      44M  1.1M 40M 3% /disk2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls -l /disk1/Videos/</span></span>
<span class="line"><span>total 1</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Our Wedding.mkv</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls -l /disk2/Videos/</span></span>
<span class="line"><span>total 2</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Baby&#39;s first Xmas.mkv</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 0 Mar 8 17:21 Halloween hijinks.mkv</span></span></code></pre></div><p>在此例中掛載了兩塊磁盤，分別為 <code>disk1</code> 和 <code>disk2</code>。兩個驅動器都有一個包含文件的 <code>Videos</code> 目錄。</p><p>現在，我們將使用 mergefs 掛載這些驅動器，使它們看起來像一個更大的驅動器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mergerfs -o defaults,allow_other,use_ino,category.create=mfs,moveonenospc=true,minfreespace=1M /disk1:/disk2 /media</span></span></code></pre></div><p>mergefs 手冊頁非常龐雜，因此我們將説明上面提到的選項。</p><ul><li><code>defaults</code>：除非指定，否則將使用默認設置。</li><li><code>allow_other</code>：允許 <code>sudo</code> 或 <code>root</code> 以外的用户查看文件系統。</li><li><code>use_ino</code>：讓 mergefs 提供文件/目錄 inode 而不是 libfuse。雖然不是默認值，但建議你啓用它，以便鏈接的文件共享相同的 inode 值。</li><li><code>category.create=mfs</code>：根據可用空間在驅動器間傳播文件。</li><li><code>moveonenospc=true</code>：如果啓用，那麼如果寫入失敗，將進行掃描以查找具有最大可用空間的驅動器。</li><li><code>minfreespace=1M</code>：最小使用空間值。</li><li><code>disk1</code>：第一塊硬盤。</li><li><code>disk2</code>：第二塊硬盤。</li><li><code>/media</code>：掛載驅動器的目錄。</li></ul><p>看起來是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -hT | grep disk</span></span>
<span class="line"><span>/dev/sdb1  ext4           23M      386K 21M 2% /disk1</span></span>
<span class="line"><span>/dev/sdc1  ext4           44M      1.1M 40M 3% /disk2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ df -hT | grep media</span></span>
<span class="line"><span>1:2        fuse.mergerfs  66M      1.4M 60M 3% /media</span></span></code></pre></div><p>你可以看到現在 mergefs 掛載顯示的總容量為 66M，這是兩塊硬盤的總容量。</p><p>繼續示例：</p><p>有一個叫 <code>Baby&#39;s second Xmas.mkv</code> 的 30M 視頻。讓我們將其複製到用 mergerfs 掛載的 <code>/media</code> 文件夾中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lh &quot;Baby&#39;s second Xmas.mkv&quot;</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 30M Apr 20 08:45 Baby&#39;s second Xmas.mkv</span></span>
<span class="line"><span>$ cp &quot;Baby&#39;s second Xmas.mkv&quot; /media/Videos/</span></span></code></pre></div><p>這是最終結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -hT | grep disk</span></span>
<span class="line"><span>/dev/sdb1  ext4          23M 386K 21M 2% /disk1</span></span>
<span class="line"><span>/dev/sdc1  ext4          44M 31M 9.8M 76% /disk2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ df -hT | grep media</span></span>
<span class="line"><span>1:2        fuse.mergerfs 66M 31M 30M 51% /media</span></span></code></pre></div><p>從磁盤空間利用率中可以看到，因為 <code>disk1</code> 沒有足夠的可用空間，所以 mergefs 自動將文件複製到 <code>disk2</code>。</p><p>這是所有文件詳情：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /disk1/Videos/</span></span>
<span class="line"><span>total 1</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Our Wedding.mkv</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls -l /disk2/Videos/</span></span>
<span class="line"><span>total 30003</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Baby&#39;s first Xmas.mkv</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 30720000 Apr 20 08:47 Baby&#39;s second Xmas.mkv</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 0 Mar 8 17:21 Halloween hijinks.mkv</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls -l /media/Videos/</span></span>
<span class="line"><span>total 30004</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Baby&#39;s first Xmas.mkv</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 30720000 Apr 20 08:47 Baby&#39;s second Xmas.mkv</span></span>
<span class="line"><span>-rw-rw-r--. 1 curt curt 0 Mar 8 17:21 Halloween hijinks.mkv</span></span>
<span class="line"><span>-rw-r--r--. 1 curt curt 0 Mar 8 17:17 Our Wedding.mkv</span></span></code></pre></div><p>當你將文件複製到 mergefs 掛載點時，它將始終將文件複製到有足夠可用空間的硬盤上。如果池中的所有驅動器都沒有足夠的可用空間，那麼你將無法複製它們。</p><hr>`,24)),n("p",null,[s[8]||(s[8]=a("via: ",-1)),i(e,{href:"https://fedoramagazine.org/using-mergerfs-to-increase-your-virtual-storage/"},{default:p(()=>[...s[7]||(s[7]=[a("https://fedoramagazine.org/using-mergerfs-to-increase-your-virtual-storage/",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("作者：",-1)),i(e,{href:"https://fedoramagazine.org/author/rcurtiswarfield/"},{default:p(()=>[...s[9]||(s[9]=[a("Curt Warfield",-1)])]),_:1}),s[14]||(s[14]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[11]||(s[11]=[a("geekpi",-1)])]),_:1}),s[16]||(s[16]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[18]||(s[18]=[a("Linux中國",-1)])]),_:1}),s[21]||(s[21]=a(" 榮譽推出",-1))])])}const M=r(g,[["render",u]]);export{y as __pageData,M as default};
